<?php
declare(strict_types=1);

$params = [];
foreach (['start_day','end_day','ticker_set','balance','fee','interval','exclude_last_intervals','symbols'] as $key) {
    if (isset($_GET[$key]) && is_scalar($_GET[$key])) $params[$key] = (string) $_GET[$key];
}
$excludedIntervals = filter_var($params['exclude_last_intervals'] ?? '1', FILTER_VALIDATE_INT);
if ($excludedIntervals === false || $excludedIntervals < 0 || $excludedIntervals > 2) $excludedIntervals = 1;
if (($params['interval'] ?? 'none') === 'none') $excludedIntervals = 0;
$params['exclude_last_intervals'] = (string) $excludedIntervals;
$params['all_pairs'] = '1';
$query = http_build_query($params);
?>
