:root{color-scheme:dark;--bg:#0b1020;--panel:#131a2d;--muted:#8995ad;--text:#e9eefb;--line:#273149;--green:#42d6a4;--red:#ff7188}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 system-ui,sans-serif}.wrap{padding:24px;max-width:1900px;margin:auto}h1{font-size:24px}.muted{color:var(--muted)}.status{padding:14px;background:var(--panel);border:1px solid var(--line);border-radius:10px;margin:14px 0}.filters{display:flex;gap:14px;flex-wrap:wrap;margin:16px 0}.filters label{display:grid;gap:5px;color:var(--muted)}select{min-width:190px;padding:8px;color:var(--text);background:#18233d;border:1px solid #52658d;border-radius:7px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{border-collapse:collapse;width:100%;min-width:1300px;font-variant-numeric:tabular-nums}th,td{padding:9px 10px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}th{position:sticky;top:0;background:#18233d;color:#cbd5ea;z-index:1}th[data-sort]{cursor:pointer}th[data-sort]:hover,th[data-sort]:focus{color:white;text-decoration:underline}td:first-child,th:first-child,td:nth-child(2),th:nth-child(2){text-align:left}tbody tr:hover{background:#18233d}.gain{color:var(--green)}.loss{color:var(--red)}a{color:#a9bcff}button{color:var(--text);background:#18233d;border:1px solid #52658d;border-radius:7px;padding:5px 9px;cursor:pointer}.detail-cell{padding:14px!important;background:#0c1222;text-align:left!important}.detail-table{min-width:900px;margin:6px 0}.excluded-interval-row{background:#493b1a!important;outline:1px solid #d9b34c}.excluded-interval-row td:first-child{color:#ffe18a;font-weight:700}.pager{display:flex;gap:12px;align-items:center;margin:12px 0}.interval-note{color:var(--muted);font-size:12px}
