<script>
const statusNode=document.querySelector('#status'),rowsNode=document.querySelector('#rows'),pageLabel=document.querySelector('#page-label'),previousPage=document.querySelector('#previous-page'),nextPage=document.querySelector('#next-page'),longFilter=document.querySelector('#long-filter'),shortFilter=document.querySelector('#short-filter'),url=new URL('hedge-ranking.php',location.href);url.search=<?= json_encode($query, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;let allPairs=[],filteredPairs=[],currentPage=0,sortKey='maximum_interval_ratio',sortDescending=true;const excludedIntervalCount=Math.max(0,Math.min(2,Number(<?= json_encode((int) ($params['exclude_last_intervals'] ?? 1)) ?>)||0)),pageSize=100;
const number=(value,digits=2)=>value===null||value===undefined||!Number.isFinite(Number(value))?'—':Number(value).toLocaleString('ru-RU',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const percent=(value,balance)=>value===null||value===undefined?'—':number(Number(value)/Number(balance)*100)+'%';
const sortValue=(pair,key)=>key.split('.').reduce((value,part)=>value?.[part],pair);
const sortFilteredPairs=()=>{filteredPairs.sort((left,right)=>{const a=sortValue(left,sortKey),b=sortValue(right,sortKey);if(a===null||a===undefined)return b===null||b===undefined?0:1;if(b===null||b===undefined)return -1;const result=typeof a==='string'?a.localeCompare(b,'en'):(Number(a)-Number(b));return sortDescending?-result:result})};
const render=data=>{const balance=Number(data.starting_balance),start=currentPage*pageSize,visible=filteredPairs.slice(start,start+pageSize),elements=[];visible.forEach((pair,offset)=>{const rank=start+offset+1,tr=document.createElement('tr'),detail=document.createElement('tr'),detailCell=document.createElement('td');detail.hidden=true;detail.dataset.detailFor=String(rank);detailCell.colSpan=9;detailCell.className='detail-cell';detailCell.innerHTML='<span class="interval-note">Нажмите «Интервалы», чтобы загрузить полную таблицу этой пары.</span>';const values=[rank,pair.long_symbol,pair.short_symbol,`${number(pair.net_pnl)} USDT (${percent(pair.net_pnl,balance)})`,pair.maximum_drawdown_percent===null?'—':number(pair.maximum_drawdown_percent)+'%',number(pair.overall_peak_drawdown_ratio),`${number(pair.worst_interval?.net_pnl)} USDT (${percent(pair.worst_interval?.net_pnl,balance)})`,pair.maximum_drawdown_interval?.maximum_drawdown_percent===null||pair.maximum_drawdown_interval?.maximum_drawdown_percent===undefined?'—':number(pair.maximum_drawdown_interval.maximum_drawdown_percent)+'%',number(pair.maximum_interval_ratio)];values.forEach((value,i)=>{const td=document.createElement('td');td.textContent=value;if(i===3||i===6)td.className=Number(i===3?pair.net_pnl:pair.worst_interval?.net_pnl)>=0?'gain':'loss';if(i===0){const button=document.createElement('button');button.type='button';button.dataset.detailButton=String(rank);button.textContent='Интервалы';td.append(document.createTextNode(' '),button)}tr.append(td)});detail.append(detailCell);elements.push(tr,detail)});rowsNode.replaceChildren(...elements);const pages=Math.max(1,Math.ceil(filteredPairs.length/pageSize));pageLabel.textContent=`Страница ${currentPage+1} из ${pages} · строк ${filteredPairs.length?start+1:0}–${Math.min(start+pageSize,filteredPairs.length)} из ${filteredPairs.length.toLocaleString('ru-RU')}`;previousPage.disabled=currentPage===0;nextPage.disabled=currentPage>=pages-1;const sortTitle=sortHeaders.find(header=>header.dataset.sort===sortKey)?.textContent.trim()||'—';statusNode.textContent=`Показано ${filteredPairs.length.toLocaleString('ru-RU')} из ${allPairs.length.toLocaleString('ru-RU')} направленных пар. Сортировка: ${sortTitle} (${sortDescending?'по убыванию':'по возрастанию'}).`};
rowsNode.addEventListener('click',async event=>{const button=event.target.closest('[data-detail-button]');if(!button)return;const rank=Number(button.dataset.detailButton),detail=rowsNode.querySelector(`[data-detail-for="${rank}"]`),cell=detail.firstElementChild;if(!detail.hidden){detail.hidden=true;button.textContent='Интервалы';return}detail.hidden=false;button.textContent='Скрыть';if(cell.dataset.loaded==='1')return;cell.textContent='Загружаю интервалы…';try{const pair=filteredPairs[rank-1],params=new URLSearchParams(url.search);params.delete('all_pairs');params.set('long_symbol',pair.long_symbol);params.set('short_symbol',pair.short_symbol);const response=await fetch(new URL('hedge-data.php?'+params.toString(),location.href),{headers:{Accept:'application/json'},cache:'no-store'}),data=await response.json();if(!response.ok||data.status==='error')throw new Error(data.message||'Не удалось загрузить интервалы');const table=document.createElement('table');table.className='detail-table';const head=document.createElement('thead'),headRow=document.createElement('tr');for(const title of ['Период','Лонг','Шорт','Общий итог','Максимум за период','Максимальное снижение на графике','Максимум / снижение']){const th=document.createElement('th');th.textContent=title;headRow.append(th)}head.append(headRow);const body=document.createElement('tbody');for(const [rowIndex,row] of (data.interval_rows||[]).entries()){const tr=document.createElement('tr');if(rowIndex<excludedIntervalCount)tr.className='excluded-interval-row';const values=[`${new Date(Number(row.start_ms)).toLocaleDateString('ru-RU',{timeZone:'Europe/Kyiv'})} — ${new Date(Number(row.end_ms)-1).toLocaleDateString('ru-RU',{timeZone:'Europe/Kyiv'})}`,`${number(row.long_pnl,4)} USDT (${percent(row.long_pnl,data.starting_balance)})`,`${number(row.short_pnl,4)} USDT (${percent(row.short_pnl,data.starting_balance)})`,`${number(row.net_pnl,4)} USDT (${percent(row.net_pnl,data.starting_balance)})`,`${number(row.maximum_net_pnl,4)} USDT (${percent(row.maximum_net_pnl,data.starting_balance)})`,`${number(row.maximum_drawdown,4)} USDT (${row.maximum_drawdown_percent===null||row.maximum_drawdown_percent===undefined?'—':number(row.maximum_drawdown_percent)+'%'})`,number(row.peak_drawdown_ratio,4)];values.forEach((value,index)=>{const td=document.createElement('td');td.textContent=value;if(index>0&&index<6)td.className=Number(index===5?row.maximum_drawdown:row[['','long_pnl','short_pnl','net_pnl','maximum_net_pnl'][index]])<0?'loss':'gain';tr.append(td)});body.append(tr)}table.append(head,body);cell.replaceChildren(table);cell.dataset.loaded='1'}catch(error){cell.textContent='Ошибка: '+error.message}});
const applyFilters=()=>{const long=longFilter.value,short=shortFilter.value;filteredPairs=allPairs.filter(pair=>(!long||pair.long_symbol===long)&&(!short||pair.short_symbol===short));sortFilteredPairs();currentPage=0;render({})};
for(const filter of [longFilter,shortFilter])filter.addEventListener('change',applyFilters);
const sortHeaders=[...document.querySelectorAll('th[data-sort]')];const changeSort=header=>{const nextKey=header.dataset.sort;if(sortKey===nextKey)sortDescending=!sortDescending;else{sortKey=nextKey;sortDescending=nextKey!=='long_symbol'&&nextKey!=='short_symbol'}sortFilteredPairs();currentPage=0;sortHeaders.forEach(item=>item.setAttribute('aria-sort',item===header?(sortDescending?'descending':'ascending'):'none'));render({})};for(const header of sortHeaders){header.addEventListener('click',()=>changeSort(header));header.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();changeSort(header)}})}sortHeaders.find(header=>header.dataset.sort===sortKey)?.setAttribute('aria-sort','descending');
previousPage.addEventListener('click',()=>{if(currentPage>0){currentPage--;render({})}});nextPage.addEventListener('click',()=>{if((currentPage+1)*pageSize<allPairs.length){currentPage++;render({})}});
(async()=>{try{const response=await fetch(url,{headers:{Accept:'application/x-ndjson, application/json'},cache:'no-store'});let result=null;if(response.headers.get('content-type')?.includes('application/x-ndjson')){const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const{value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);if(event.type==='progress')statusNode.textContent=event.message;if(event.type==='error')throw new Error(event.message);if(event.type==='result')result=event.data}}buffer+=decoder.decode();if(buffer.trim()){const event=JSON.parse(buffer);if(event.type==='error')throw new Error(event.message);if(event.type==='result')result=event.data}}else result=await response.json();if(!response.ok||result?.status!=='ready')throw new Error(result?.message||'Расчёт пар завершился с ошибкой');allPairs=result.pairs||[];const symbols=[...new Set(result.symbols||allPairs.flatMap(pair=>[pair.long_symbol,pair.short_symbol]))].sort((a,b)=>a.localeCompare(b,'en'));for(const symbol of symbols){for(const filter of [longFilter,shortFilter]){const option=document.createElement('option');option.value=symbol;option.textContent=symbol;filter.append(option)}}applyFilters()}catch(error){statusNode.classList.add('loss');statusNode.textContent='Ошибка расчёта: '+error.message}})();
